SELECT w.id AS wallet_id, w.execution_reason, s.id AS one_id, s.symbol, s.candle_open_time, s.generated_at AS one_gen, (SELECT u.id FROM trade_signal u WHERE u.symbol = s.symbol AND u.interval_code = '5m' AND u.generated_at <= s.generated_at ORDER BY u.generated_at DESC LIMIT 1) AS used5_id, (SELECT u.decision FROM trade_signal u WHERE u.symbol = s.symbol AND u.interval_code = '5m' AND u.generated_at <= s.generated_at ORDER BY u.generated_at DESC LIMIT 1) AS used5_decision, f.id AS same5_id, f.decision AS same5_decision, f.atr_immediate_entry_allowed AS same5_imm, p.realized_pnl, p.close_reason FROM wallet_trade w JOIN trade_signal s ON s.id = w.signal_id LEFT JOIN trade_signal f ON f.symbol = s.symbol AND f.interval_code = '5m' AND f.candle_open_time = s.candle_open_time - INTERVAL 4 MINUTE LEFT JOIN paper_position p ON p.signal_id = w.signal_id WHERE w.side = 'BUY' AND s.interval_code = '1m' AND MOD(MINUTE(s.candle_open_time)+1,5) = 0 AND w.execution_reason <> 'SETUP_CONFIRMATION_WAKEUP' ORDER BY w.id LIMIT 200